create table if not exists users(id bigserial primary key,email text unique not null,role text not null default 'viewer',created_at timestamptz default now());
create table if not exists branches(id bigserial primary key,name text unique not null,active boolean default true);
create table if not exists month_closings(id bigserial primary key,month date not null,branch_id bigint references branches(id),opening jsonb not null default '{}',closing jsonb not null default '{}',monthly_kisti_count integer,closed_by bigint references users(id),closed_at timestamptz default now(),unique(month,branch_id));
create table if not exists daily_entries(id bigserial primary key,entry_date date not null,branch_id bigint references branches(id),actual_member integer,actual_loanee integer,savings numeric,today_disbursement numeric,grant_total_disbursement numeric,loan_outstanding numeric,overdue_outstanding numeric,recovery_rate numeric,cash_in_hand numeric,bank numeric,created_by bigint references users(id),created_at timestamptz default now(),unique(entry_date,branch_id));
